var n=`0868-seekh-kebab`;var a=`world-0868`;var s=`PK`;var t=`south-asia`;var o=4;var l=49;var r={en:`Seekh Kebab`,ua:`Сікх-кебаб`};var g={en:`Seekh Kebab is a Pakistan dish made with ground lamb, yellow onion, ginger-garlic paste, cilantro. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Сікх-кебаб, страва кухні країни Пакистан. Основні складники: фарш з ягнятини, жовта цибуля, імбирно-часникова паста, кінза. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:14,i:[[`ground-lamb`,720,`g`],[`yellow-onion`,135,`g`],[`ginger-garlic-paste`,25,`g`],[`garam-masala`,8,`g`],[`cilantro`,20,`g`],[`table-salt`,null,`to_taste`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:15,i:[]},{en:`Grill over medium-high heat for about 17 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 17 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:17,i:[[`canola-oil`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon`,1,`pcs`],[`red-onion`,100,`g`]]}];var h={slug:n,id:a,country:`PK`,region:t,servings:4,minutes:49,title:r,text:g,steps:d};export{s as country,h as default,a as id,l as minutes,t as region,o as servings,n as slug,d as steps,g as text,r as title};